SELECT C1, C2, C3, MATCH_NUMBER() AS MN, CLASSIFIER() AS CL
FROM DB1.S3.T5
MATCH_RECOGNIZE (
    PARTITION BY C1
    ORDER BY C2
    MEASURES FIRST(C3) AS ST
    ONE ROW PER MATCH
    AFTER MATCH SKIP PAST LAST ROW
    PATTERN (UP+ DOWN+)
    DEFINE
        UP AS C3 > LAG(C3),
        DOWN AS C3 < LAG(C3)
);
